const input = $input.first().json || {};
let month = (input.month || '').toString().trim();
if (!/^\d{4}-\d{2}$/.test(month)) month = $now.minus({ months: 1 }).toFormat('yyyy-MM');
const start = DateTime.fromFormat(month, 'yyyy-MM', { zone: 'Asia/Ho_Chi_Minh' }).startOf('month');
return [{ json: { month, start: start.toISO(), end: start.plus({ months: 1 }).toISO() } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });

const { month } = $('Target month').first().json;
const ctx = $('Get context').first().json;
const offers = rowsOf('Load offers').filter((o) => o.status !== 'proposed');
const pieces = rowsOf('Load pieces');
if (!pieces.length && !offers.length) return [{ json: { skip: true, text: `Nothing to review for ${month}.`, purpose: 'retro' } }];

const count = (xs, key) => xs.reduce((m, x) => ({ ...m, [x[key]]: (m[x[key]] || 0) + 1 }), {});
const decided = pieces.filter((p) => ['approved', 'scheduled', 'published', 'rejected'].includes(p.status));
const firstTry = decided.filter((p) => p.status !== 'rejected' && Number(p.revisions) === 1 && !p.feedback).length;
const engagement = (p) => (Number(p.reaction_count) || 0) + 2 * (Number(p.comment_count) || 0) + 3 * (Number(p.share_count) || 0);
const hasMetrics = pieces.some((p) => p.metrics_at);

const stats = [
  `Month ${month}. Pieces: ${pieces.length}. By kind: ${JSON.stringify(count(pieces, 'kind'))}. By status: ${JSON.stringify(count(pieces, 'status'))}.`,
  `Approved on the first draft without change requests: ${firstTry} of ${decided.length} decided.`,
  hasMetrics ? '' : 'No engagement numbers were collected this month.',
  '',
  'Offers:',
  ...offers.map((o) => `- ${o.title} | ${o.product} | ${o.offer_type}: ${o.offer} | reason (${o.reason_type}): ${o.reason} | ${o.launch_date} to ${o.ends_on} | ${o.status} | sales ${o.sales_count ?? 'not reported'}, revenue ${o.revenue ?? 'not reported'} | notes: ${o.result_notes || '-'}`),
  '',
  'Pieces in date order:',
  ...pieces.map((p) => [
    `- ${parseDt(p.publish_at).toFormat('dd/MM')} ${p.kind} [${p.status}] offer #${p.offer_id || '-'}: ${p.title}`,
    `  drafts ${p.revisions || 0}, check ${p.check_passed ? 'passed' : 'not passed'}${hasMetrics ? `, reactions ${p.reaction_count ?? '-'}, comments ${p.comment_count ?? '-'}, shares ${p.share_count ?? '-'}, score ${engagement(p)}` : ''}`,
    p.feedback ? `  author change requests: ${p.feedback.replace(/\n+/g, ' ').slice(0, 500)}` : '',
    p.draft ? `  opening: ${p.draft.slice(0, 160).replace(/\n+/g, ' ')}` : '',
  ].filter(Boolean).join('\n')),
].join('\n');

return [{ json: { skip: false, month, stats, prompt: `${stats}\n\nRules in force this month:\n${ctx.rules || '(none)'}` } }];

const input = $('Build retro input').first().json;
const text = ($json.text || '').toString();
const m = text.match(/SUMMARY\s*\n([\s\S]*?)\n\s*RULES\s*\n([\s\S]*)$/i);
const summary = (m ? m[1] : text).trim();
const rules = (m ? m[2] : '').split('\n').map((l) => l.trim()).filter((l) => l.startsWith('- ')).join('\n');
if (!rules) throw new Error('The retro has no RULES section: ' + text.slice(0, 300));
return [{ json: { month: input.month, summary, rules, stats: input.stats } }];

const r = $('Parse retro').first().json;
return [{
  json: {
    text: `🔁 Retro for ${r.month}\n\n${r.summary}\n\nRules from now on:\n${r.rules}\n\nReply to this message to add or correct a rule.`,
    ref: `retro:${$json.id}`,
    purpose: 'retro',
  },
}];
